const office = {
  time_zone: 'YOUR_TIME_ZONE',
  weekly_hours: { Monday: [['09:00','17:00']], Tuesday: [['09:00','17:00']], Wednesday: [['09:00','17:00']], Thursday: [['09:00','17:00']], Friday: [['09:00','17:00']], Saturday: [], Sunday: [] },
  closed_dates: []
};
return [{ json: office }];

const c = $input.first().json;
const clock = new Date();
const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const minuteOf = text => {
  if (!/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(text)) throw new Error('Hours must use HH:MM');
  const [h,m] = text.split(':').map(Number); return h*60+m;
};
if (c.time_zone === 'YOUR_TIME_ZONE') throw new Error('Configure the office time zone');
const f = new Intl.DateTimeFormat('en-US', { timeZone: c.time_zone, weekday:'long', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', minute:'2-digit', hourCycle:'h23' });
const p = Object.fromEntries(f.formatToParts(clock).map(part => [part.type, part.value]));
const date = [p.year,p.month,p.day].join('-');
const nowMinute = Number(p.hour)*60+Number(p.minute);
const today = c.weekly_hours[p.weekday] || [];
const previousDay = weekdays[(weekdays.indexOf(p.weekday)+6)%7];
const previousDateObject = new Date(Date.UTC(Number(p.year),Number(p.month)-1,Number(p.day)-1));
const previousDate = previousDateObject.toISOString().slice(0,10);
const closures = Array.isArray(c.closed_dates) ? c.closed_dates : [];
for (const day of weekdays) for (const pair of c.weekly_hours[day] || []) {
  if (!Array.isArray(pair) || pair.length !== 2 || minuteOf(pair[0]) === minuteOf(pair[1])) throw new Error('Each interval needs distinct start and end times');
}
const openToday = today.some(([a,b]) => { const start=minuteOf(a), end=minuteOf(b); return end>start ? nowMinute>=start && nowMinute<end : nowMinute>=start; });
const openOvernight = !closures.includes(previousDate) && (c.weekly_hours[previousDay] || []).some(([a,b]) => minuteOf(b)<minuteOf(a) && nowMinute<minuteOf(b));
const open = !closures.includes(date) && (openToday || openOvernight);
return [{ json: { status: open ? 'open' : 'closed', office_is_open: open, local_date: date, local_day: p.weekday, local_time: p.hour+':'+p.minute, time_zone: c.time_zone, today_hours: today, closed_date: closures.includes(date) } }];
